+            Snackbar.Add(successMessage, Severity.Success);
+        }
+        catch (JSException)
+        {
+            Snackbar.Add("Unable to copy. Check browser clipboard permissions.", Severity.Warning);
+        }
+    }
+
+    private async Task ScrollToBottomAsync()
+    {
+        try
+        {
