+    }
+
+    private static string StripAnsi(string text)
+    {
+        var builder = new StringBuilder(text.Length);
+        var inEscape = false;
+
+        foreach (var character in text)
+        {
+            if (character == '\u001b')
+            {
+                inEscape = true;
+                continue;
+            }
+
+            if (inEscape)
+            {
+                if (char.IsLetter(character))
+                    inEscape = false;
+
+                continue;
+            }
+
+            builder.Append(character);
+        }
+
+        return builder.ToString();
+    }
